document.documentElement.classList.add('js');
const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle?.getAttribute('aria-expanded')==='true'){toggle.setAttribute('aria-expanded','false');nav.classList.remove('open');toggle.focus()}});
const search=document.querySelector('#guide-search');search?.addEventListener('input',()=>{const query=search.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-search]').forEach(card=>{card.hidden=!card.dataset.search.toLowerCase().includes(query);if(!card.hidden)count++});document.querySelector('#search-count').textContent=count+' guide'+(count===1?'':'s');document.querySelector('#empty-search').hidden=count>0});
const cityCards=[...document.querySelectorAll('[data-city-card]')];const cityPrev=document.querySelector('[data-city-page="prev"]');const cityNext=document.querySelector('[data-city-page="next"]');const cityLabel=document.querySelector('[data-city-page-label]');if(cityCards.length&&cityPrev&&cityNext&&cityLabel){let page=0;const perPage=3;const render=()=>{const pages=Math.ceil(cityCards.length/perPage);cityCards.forEach((card,i)=>{card.hidden=Math.floor(i/perPage)!==page});cityLabel.textContent=`Page ${page+1} of ${pages}`;cityPrev.disabled=page===0;cityNext.disabled=page===pages-1};cityPrev.addEventListener('click',()=>{if(page>0){page--;render()}});cityNext.addEventListener('click',()=>{if(page<Math.ceil(cityCards.length/perPage)-1){page++;render()}});render()}

